<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref} from 'vue';
import {AlertCircle,ArrowDown,ArrowUp,CalendarClock,Check,CheckCircle2,ChevronRight,LoaderCircle,Pencil,Plus,RefreshCw,Search,ShieldCheck,Trash2,X} from 'lucide-vue-next';
import ApprovalReview from './ApprovalReview.vue';
import {createRequestGuard} from '../lib/async-response';
import {conversationReviewState} from '../lib/conversation-approvals';
import {newScheduleTrigger,scheduleChangeCount,scheduleContextLabel,scheduleDraft,schedulePatch,scheduleTriggerTypes,sourceContextMode,sourceContextModes} from '../lib/schedule-editor';
type Item=Record<string,any>;
const props=defineProps<{tenant:string;tenantName:string;resource?:Item|null;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const emit=defineEmits<{close:[];updated:[];saved:[resource:string];notice:[message:string]}>();
const editing=computed(()=>!!props.resource);const opened=ref(!props.resource);const loading=ref(false);const busy=ref(false);const error=ref('');const options=ref<Item|null>(null);const draft=ref<Item|null>(null);const search=ref('');const review=ref<Item|null>(null);const clock=ref(Date.now());const uncertain=ref(false);const polling=ref(false);const checking=ref(false);const requestId=ref(crypto.randomUUID());const nameInput=ref<HTMLInputElement|null>(null);
const guard=createRequestGuard();const fieldId='schedule-'+crypto.randomUUID();let timer:ReturnType<typeof setInterval>|undefined;let completionSent=false;
const status=computed(()=>review.value?conversationReviewState(review.value,clock.value):'');
const running=computed(()=>['approved','executing'].includes(status.value));
const result=computed<Item>(()=>review.value?.payload?.execution?.result??{});
const attempt=computed<Item>(()=>review.value?.payload?.schedule_attempt??{});
const verification=computed<Item|null>(()=>review.value?.payload?.schedule_verification??null);
const targetResource=computed(()=>result.value.resource??attempt.value.resource??attempt.value.created_resource??props.resource?.ref??'');
const protectedDaily=computed(()=>Boolean(options.value?.configuration?.daily_protected));
const patch=computed(()=>options.value&&draft.value?schedulePatch(options.value,draft.value):{});
const changed=computed(()=>scheduleChangeCount(patch.value));
const flows=computed<Item[]>(()=>options.value?.flows??[]);
const sourceById=computed<Record<string,Item>>(()=>Object.fromEntries(flows.value.map(flow=>[flow.id,flow])));
const available=computed(()=>flows.value.filter(flow=>(!draft.value?.agent||flow.agent_id===draft.value.agent)&&(!search.value||flow.name.toLocaleLowerCase('pt-BR').includes(search.value.toLocaleLowerCase('pt-BR')))));
const invalidSources=computed(()=>draft.value?.flows.some((row:Item)=>{const flow=sourceById.value[row.flow_id];return !flow?.eligible||flow.agent_id!==draft.value?.agent;})??false);
const canPrepare=computed(()=>draft.value&&changed.value>0&&draft.value.name.trim()&&draft.value.agent&&draft.value.flows.length&&draft.value.triggers.length&&!invalidSources.value);
const days=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
function sourceName(row:Item){return sourceById.value[row.flow_id]?.name??'Fonte indisponível';}
function otherSchedules(flow:Item):Item[]{return (flow.schedules??[]).filter((schedule:Item)=>'schedule:'+schedule.id!==props.resource?.ref);}
function selected(flow:Item){return draft.value?.flows.some((row:Item)=>String(row.flow_id)===String(flow.id)&&row.context!=='KeySweep');}
function addSource(flow:Item){if(!draft.value||!flow.eligible||selected(flow))return;if(!draft.value.agent)draft.value.agent=flow.agent_id;draft.value.flows.push({_uid:crypto.randomUUID(),flow_id:flow.id,context:flow.load_type==='Incremental'?'Incremental':flow.load_type==='Temporal'?'Temporal:Days:30':'Total'});}
function move(rows:Item[],index:number,offset:number){const target=index+offset;if(target<0||target>=rows.length)return;[rows[index],rows[target]]=[rows[target],rows[index]];}
function mode(row:Item,value:string){const year=new Date().getFullYear();row.context=value==='Current'?'Temporal:Year:Current':value==='Days'||value==='Future'?`Temporal:${value}:30`:value==='Month'?`Temporal:Month:1-${year}`:value==='Year'?`Temporal:Year:${year}`:value;}
function temporalValue(row:Item){return row.context.split(':')[2]??'';}
function monthValue(row:Item){const [month,year]=temporalValue(row).split('-');return `${year}-${String(month).padStart(2,'0')}`;}
function updateMonth(row:Item,value:string){if(!/^\d{4}-\d{2}$/.test(value))return;const [year,month]=value.split('-');row.context=`Temporal:Month:${Number(month)}-${year}`;}
function triggerType(row:Item,value:string){Object.assign(row,newScheduleTrigger(options.value?.default_anchor??'',value),{_uid:row._uid});}
function editableTrigger(row:Item){return scheduleTriggerTypes.some(type=>type.value===row.type);}
async function begin(){
 const current=guard.next();opened.value=true;loading.value=true;busy.value=false;polling.value=false;checking.value=false;error.value='';options.value=null;draft.value=null;review.value=null;uncertain.value=false;completionSent=false;requestId.value=crypto.randomUUID();
 try{const data=await props.request(`/catalog/${props.tenant}/schedules/${props.resource?props.resource.id+'/configuration':'options'}`);if(!current())return;options.value=data;draft.value=scheduleDraft(data);search.value='';}
 catch(e){if(current())error.value=(e as Error).message;}
 finally{if(current()){loading.value=false;await nextTick();nameInput.value?.focus();}}
}
async function prepare(){
 if(!canPrepare.value||busy.value||!draft.value)return;const current=guard.current();busy.value=true;error.value='';
 try{const response=await props.request(`/catalog/${props.tenant}/schedules/actions`,'POST',{action:editing.value?'update_schedule':'create_schedule',request_id:requestId.value,...patch.value});if(!current())return;review.value=response.approval;emit('updated');}
 catch(e){if(current())error.value=(e as Error).message;}
 finally{if(current())busy.value=false;}
}
function notifyCompletion(){if(status.value!=='completed'||completionSent)return;completionSent=true;emit('updated');emit('notice',result.value.message??'Agenda salva e conferida no BI.');}
async function refreshStatus(force=false){
 if(polling.value||!review.value||(!force&&!running.value&&!uncertain.value))return;const current=guard.current();const id=review.value.id;polling.value=true;
 try{const response=await props.request(`/bi-actions/${id}`);if(!current()||review.value?.id!==id)return;review.value=response.approval;uncertain.value=false;error.value='';notifyCompletion();}
 catch(e){if(current())error.value=(e as Error).message;}
 finally{if(current())polling.value=false;}
}
async function decide(decision:'approved'|'rejected'){
 if(status.value!=='pending'||busy.value||uncertain.value||!review.value)return;const current=guard.current();busy.value=true;error.value='';
 try{const response=await props.request(`/approvals/${review.value.id}/decide`,'POST',{decision,fingerprint:review.value.fingerprint});if(!current())return;review.value=response;emit('updated');if(decision==='approved')await refreshStatus(true);}
 catch(e){if(current()){uncertain.value=true;error.value=(e as Error).message;}}
 finally{if(current())busy.value=false;}
}
async function verify(){
 if(!review.value||checking.value)return;const current=guard.current();checking.value=true;error.value='';
 try{const response=await props.request(`/bi-actions/${review.value.id}/schedule-verification`,'POST');if(!current())return;review.value=response.approval;emit('updated');}
 catch(e){if(current())error.value=(e as Error).message;}
 finally{if(current())checking.value=false;}
}
function close(){guard.invalidate();if(editing.value)opened.value=false;else emit('close');}
onMounted(()=>{if(!editing.value)begin();timer=setInterval(()=>{clock.value=Date.now();if(!document.hidden)refreshStatus();},2200);});
onUnmounted(()=>{guard.invalidate();if(timer)clearInterval(timer);});
</script>

<template>
 <section class="schedule-form" aria-label="Configurar agenda" data-tour="schedule-editor">
  <button v-if="!opened" class="secondary-button" @click="begin"><Pencil :size="15"/>Editar agenda</button>
  <template v-else>
   <header class="schedule-intro"><span class="project-icon blue"><CalendarClock :size="23"/></span><div><h2>{{editing?'Editar agenda':'Nova agenda de atualização'}}</h2><p>{{tenantName}} · Escolha quais dados atualizar e quando.</p></div></header>
   <div v-if="loading" class="schedule-loading" role="status"><LoaderCircle class="spin" :size="24"/><div><strong>Conferindo fontes e agendas</strong><p>Verificamos as frequências existentes para evitar cargas duplicadas.</p></div></div>
   <form v-else-if="!review&&draft&&options" @submit.prevent="prepare">
    <fieldset :disabled="busy">
     <div class="schedule-grid"><div class="schedule-field"><label :for="fieldId+'-name'">Nome da agenda</label><input :id="fieldId+'-name'" ref="nameInput" v-model="draft.name" required maxlength="100" placeholder="Ex.: Atualização do financeiro"></div><div class="schedule-field"><label :for="fieldId+'-agent'">Agente que atualizará os dados</label><select :id="fieldId+'-agent'" v-model="draft.agent" required><option value="">Escolha um agente</option><option v-for="agent in options.agents" :key="agent.id" :value="agent.id">{{agent.name}}</option></select><small>As fontes precisam usar esse mesmo agente.</small></div></div>
     <section class="schedule-section"><h3><span class="schedule-step">1</span>Fontes e ordem da atualização</h3><p>Adicione as fontes de dados pelo nome. Elas serão processadas na ordem abaixo.</p>
      <ol v-if="draft.flows.length" class="schedule-sources"><li v-for="(row,index) in draft.flows" :key="row._uid"><div class="schedule-source-heading"><span class="schedule-order">{{Number(index)+1}}</span><strong>{{sourceName(row)}}</strong><div class="schedule-row-actions"><button type="button" class="icon-button" :disabled="index===0" :aria-label="'Mover '+sourceName(row)+' para cima'" @click="move(draft.flows,Number(index),-1)"><ArrowUp :size="15"/></button><button type="button" class="icon-button" :disabled="index===draft.flows.length-1" :aria-label="'Mover '+sourceName(row)+' para baixo'" @click="move(draft.flows,Number(index),1)"><ArrowDown :size="15"/></button><button type="button" class="icon-button" :disabled="protectedDaily&&Boolean(row.key)" :aria-label="'Remover '+sourceName(row)+' da agenda'" @click="draft.flows.splice(index,1)"><Trash2 :size="15"/></button></div></div>
       <div class="schedule-context"><label :for="fieldId+'-context-'+row._uid">Dados a atualizar</label><select :id="fieldId+'-context-'+row._uid" :value="sourceContextMode(row.context)" :disabled="(protectedDaily&&Boolean(row.key))||!sourceById[row.flow_id]?.eligible" @change="mode(row,($event.target as HTMLSelectElement).value)"><option v-if="!sourceContextModes(sourceById[row.flow_id]??{}).some(option=>option.value===sourceContextMode(row.context))" :value="sourceContextMode(row.context)">Manter a forma de carga atual</option><option v-for="option in sourceContextModes(sourceById[row.flow_id]??{})" :key="option.value" :value="option.value">{{option.label}}</option></select>
        <label v-if="['Days','Future'].includes(sourceContextMode(row.context))" class="schedule-context-value">Quantidade de dias<input type="number" min="1" max="99999" required :disabled="protectedDaily&&Boolean(row.key)" :value="temporalValue(row)" @input="row.context='Temporal:'+sourceContextMode(row.context)+':'+($event.target as HTMLInputElement).value"></label>
        <label v-if="sourceContextMode(row.context)==='Month'" class="schedule-context-value">Mês e ano<input type="month" required :disabled="protectedDaily&&Boolean(row.key)" :value="monthValue(row)" @input="updateMonth(row,($event.target as HTMLInputElement).value)"></label>
        <label v-if="sourceContextMode(row.context)==='Year'" class="schedule-context-value">Ano<input type="number" min="1900" max="9999" required :disabled="protectedDaily&&Boolean(row.key)" :value="temporalValue(row)" @input="row.context='Temporal:Year:'+($event.target as HTMLInputElement).value"></label>
       </div><p v-if="row.context==='KeySweep'" class="schedule-warning">Compara as chaves com a origem e marca os registros removidos. Não substitui uma carga de novos dados. A fonte e a tabela precisam ter a configuração de exclusões compatível.</p><p v-if="!sourceById[row.flow_id]?.eligible||sourceById[row.flow_id]?.agent_id!==draft.agent" class="schedule-warning" role="alert">Esta fonte está indisponível, privada ou usa outro agente. Confira a seleção antes de continuar.</p>
      </li></ol>
      <p v-else class="schedule-empty">Nenhuma fonte selecionada. Encontre uma fonte abaixo para começar.</p>
      <details class="schedule-picker" :open="!draft.flows.length"><summary><Plus :size="16"/>Adicionar fontes</summary><label class="schedule-source-search"><Search :size="16"/><input v-model="search" aria-label="Buscar fontes para a agenda" placeholder="Busque pelo nome da fonte…"></label><div class="schedule-source-list"><article v-for="flow in available" :key="flow.id"><div><strong>{{flow.name}}</strong><small v-if="!flow.eligible">{{flow.published?'Configuração ou agente indisponível':'Fonte privada · publique com autorização própria antes de agendar'}}</small><template v-for="existing in otherSchedules(flow)" :key="existing.id"><small>{{existing.name}} · {{existing.active?'Ativa':'Inativa'}} · {{existing.frequency}}</small><button type="button" class="schedule-text-button" @click="emit('saved','schedule:'+existing.id)">Ver essa agenda <ChevronRight :size="12"/></button></template></div><button type="button" class="secondary-button" :disabled="!flow.eligible||selected(flow)" :aria-label="'Adicionar fonte '+flow.name" @click="addSource(flow)"><Check v-if="selected(flow)" :size="14"/><Plus v-else :size="14"/>{{selected(flow)?'Adicionada':'Adicionar'}}</button></article><p v-if="!available.length" class="schedule-empty">Nenhuma fonte para esse agente ou busca.</p></div></details>
      <p v-if="draft.active&&draft.flows.some((row:Item)=>otherSchedules(sourceById[row.flow_id]??{}).some((schedule:Item)=>schedule.active)&&row.context!=='KeySweep')" class="schedule-warning" role="alert">Há fontes com outra agenda ativa. Reutilize essa agenda; a conferência impedirá criar uma segunda carga automática para a mesma fonte.</p>
     </section>
     <section class="schedule-section"><h3><span class="schedule-step">2</span>Quando atualizar</h3><p>Horários de Brasília (America/Sao_Paulo). Para cargas diárias, prefira a madrugada.</p><p v-if="protectedDaily" class="schedule-note"><ShieldCheck :size="17"/>Esta agenda já mantém uma atualização diária ou mais frequente. Os horários e as fontes existentes serão preservados. Você pode acrescentar fontes e horários e ajustar nome, ordem, agente compatível e avisos.</p>
      <article v-for="(row,index) in draft.triggers" :key="row._uid" class="schedule-trigger"><header><strong>{{row.key?row.label:'Novo horário'}}</strong><div class="schedule-row-actions"><button v-if="row.key&&!protectedDaily&&editableTrigger(row)" type="button" class="schedule-text-button" @click="row._editing=!row._editing"><Pencil :size="14"/>{{row._editing?'Recolher':'Ajustar horário'}}</button><button type="button" class="icon-button" :disabled="(protectedDaily&&Boolean(row.key))||draft.triggers.length===1" :aria-label="'Remover horário '+(Number(index)+1)" @click="draft.triggers.splice(index,1)"><Trash2 :size="15"/></button></div></header>
       <div v-if="!row.key||row._editing" class="schedule-trigger-fields"><div class="schedule-field"><label :for="fieldId+'-type-'+row._uid">Frequência</label><select :id="fieldId+'-type-'+row._uid" :value="row.type" :disabled="Boolean(row.key)" @change="triggerType(row,($event.target as HTMLSelectElement).value)"><option v-for="type in scheduleTriggerTypes" :key="type.value" :value="type.value">{{type.label}}</option></select><small v-if="row.key">Para trocar o tipo, remova este horário e adicione outro.</small></div>
        <label v-if="row.type==='Week'" class="schedule-field">Dia da semana<select v-model="row.period"><option v-for="(day,weekday) in days" :key="weekday" :value="weekday">{{day}}</option></select></label><label v-if="row.type==='Month'" class="schedule-field">Dia do mês<input v-model="row.period" type="number" required min="1" max="31"><small>Se o mês for menor, usa seu último dia.</small></label>
        <label v-if="['Day','Week','Month'].includes(row.type)" class="schedule-field">Horário<input v-model="row.time" type="time" required></label>
        <label v-if="['Hour','Minute','CDC'].includes(row.type)" class="schedule-field">{{row.type==='Hour'?'Intervalo em horas':row.type==='Minute'?'Intervalo em minutos':'Sondagem a cada (segundos)'}}<input v-model="row.period" type="number" required :min="row.type==='CDC'?5:1" :max="row.type==='Hour'?24:row.type==='Minute'?60:3600"></label>
        <template v-if="['Hour','Minute','CDC'].includes(row.type)"><label class="schedule-field">Início da janela<input v-model="row.window_start" type="time" :required="row.type!=='CDC'"></label><label class="schedule-field">Fim da janela<input v-model="row.window_end" type="time" :required="row.type!=='CDC'"></label><label class="schedule-field schedule-full">Início dos intervalos, com fuso<input v-model="row.anchor" required maxlength="40" placeholder="2026-10-31T00:00:00-03:00"><small>Data de referência para os disparos. Use uma data e hora com fuso, conforme o exemplo. A janela deve começar e terminar no mesmo dia.</small></label></template>
        <template v-if="row.type==='CDC'"><p class="schedule-note schedule-full">A detecção consulta a origem e dispara apenas quando o resultado mudar. Ela não garante uma carga diária; mantenha também um horário diário quando necessário.</p><div v-if="row.probe_configured" class="schedule-full"><label class="schedule-check"><input v-model="row._replaceProbe" type="checkbox">Substituir a consulta de detecção existente</label><p v-if="!row._replaceProbe" class="schedule-hint">A conexão e a consulta existentes serão mantidas.</p></div><div v-if="!row.probe_configured||row._replaceProbe" class="schedule-probe schedule-full"><h4>Consulta de detecção · configuração avançada</h4><p>Peça à IA para preparar a consulta se precisar. Ela deve retornar uma linha com até oito valores, como uma data de última alteração. Consultas de detecção são executadas repetidamente pelo agente.</p><label class="schedule-field">Conexão da origem<select v-model="row.probe.credential_id" required><option value="">Selecione uma conexão</option><option v-for="credential in options.credentials" :key="credential.id" :value="credential.id">{{credential.name}}</option></select></label><p v-if="!options.credentials_available" class="schedule-warning">{{options.credentials_message}}</p><label class="schedule-field">Consulta somente de leitura<textarea v-model="row.probe.sql" required rows="4" maxlength="8192" spellcheck="false" placeholder="SELECT …"></textarea></label><label class="schedule-field">Tempo máximo da consulta (segundos)<input v-model="row.probe.timeout_seconds" required type="number" min="1" :max="Math.min(300,Number(row.period)-1)"><small>Precisa ser menor que o intervalo entre sondagens.</small></label></div></template>
       </div><p v-else-if="!editableTrigger(row)" class="schedule-hint">Este tipo da origem será preservado. Você pode removê-lo e adicionar um dos tipos disponíveis.</p>
      </article><button type="button" class="secondary-button" @click="draft.triggers.push(newScheduleTrigger(options.default_anchor))"><Plus :size="15"/>Adicionar horário</button>
     </section>
     <section class="schedule-section"><h3><span class="schedule-step">3</span>Ativação e avisos</h3><label class="schedule-check"><input v-model="draft.active" type="checkbox" :disabled="protectedDaily"><span><strong>Ativar atualização automática</strong><small>{{draft.active?'As cargas poderão começar nos horários configurados após a autorização.':'A agenda será salva inativa. Você poderá conferir e ativar depois.'}}</small></span></label><details class="schedule-advanced"><summary>Avisos por e-mail e execução</summary><label class="schedule-check"><input v-model="draft.notifications.on_error" type="checkbox">Avisar quando houver erro</label><label class="schedule-check"><input v-model="draft.notifications.on_success" type="checkbox">Avisar quando concluir</label><label class="schedule-field">Destinatários<textarea v-model="draft.emails" rows="2" placeholder="Um e-mail por linha, ou separados por vírgula"></textarea></label><p class="schedule-hint">Outras opções de aviso já existentes serão preservadas.</p><label class="schedule-check"><input v-model="draft.parallel_lane" type="checkbox"><span>Usar a fila paralela do agente<small>Pode concorrer com outras cargas e aumentar o consumo da origem. A disponibilidade depende do agente.</small></span></label></details></section>
     <p class="schedule-note"><ShieldCheck :size="17"/>Salvar exige sua autorização na próxima etapa. A configuração será lida novamente no BI para confirmar o resultado. Isso não solicita uma carga de teste.</p>
     <div v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}</div><div class="schedule-footer"><span v-if="editing&&!changed" class="schedule-hint">Nenhuma alteração pendente.</span><button type="button" class="secondary-button" @click="close">Cancelar</button><button class="primary-button" :disabled="!canPrepare"><LoaderCircle v-if="busy" class="spin" :size="15"/><ShieldCheck v-else :size="15"/>Conferir alterações</button></div>
    </fieldset>
   </form>
   <div v-else-if="!review" class="schedule-load-error"><p class="form-error" role="alert">{{error}}</p><div class="schedule-footer"><button class="secondary-button" @click="close">Fechar</button><button class="primary-button" @click="begin">Tentar novamente</button></div></div>
   <template v-else>
    <template v-if="status==='pending'"><h3 class="schedule-review-title">Confira antes de autorizar</h3><ApprovalReview :approval="review" :tenants="[{id:tenant,name:tenantName}]"/><div class="schedule-footer"><button class="secondary-button" :disabled="busy||uncertain" @click="decide('rejected')"><X :size="15"/>Recusar</button><button class="primary-button" :disabled="busy||uncertain" @click="decide('approved')"><LoaderCircle v-if="busy" class="spin" :size="15"/><Check v-else :size="15"/>{{editing?'Autorizar alteração':'Autorizar criação'}}</button></div></template>
    <div v-else-if="running" class="schedule-result" role="status"><LoaderCircle class="spin" :size="24"/><div><strong>Salvando e conferindo a agenda</strong><p>A autorização foi registrada. Aguarde a confirmação da configuração no BI.</p></div></div>
    <div v-else-if="status==='completed'" class="schedule-result success" role="status"><CheckCircle2 :size="24"/><div><strong>Agenda salva · {{result.active?'Ativa':'Inativa'}}</strong><p>{{result.confirmed_name}}</p><small>{{result.message}}</small></div></div>
    <div v-else class="schedule-result" role="status"><AlertCircle :size="23"/><div><strong>{{status==='rejected'?'Solicitação recusada':status==='expired'?'Revisão expirada':status==='cancelled'?'Solicitação cancelada':'A configuração precisa de conferência'}}</strong><p>{{status==='failed'?(review.payload?.execution?.message??'Confira a agenda antes de preparar outra alteração.'):'Nenhuma nova execução será iniciada por esta revisão.'}}</p></div></div>
    <p v-if="verification" class="schedule-note" :class="{'schedule-warning':!verification.configuration_matches}" role="status">{{verification.message}}</p><div v-if="error" class="form-error" role="alert"><AlertCircle :size="16"/>{{error}}</div><p v-if="uncertain" class="schedule-note">A decisão não pôde ser confirmada. Confira a solicitação antes de tentar decidir novamente.</p>
    <div class="schedule-footer"><button v-if="uncertain||running" class="secondary-button" :disabled="polling" @click="refreshStatus(true)"><RefreshCw :size="15"/>Conferir solicitação</button><button v-if="status==='failed'&&attempt.push_started" class="secondary-button" :disabled="checking" @click="verify"><RefreshCw :size="15" :class="{spin:checking}"/>Conferir envio no BI</button><button v-if="targetResource&&!running&&status!=='pending'" class="primary-button" @click="emit('saved',targetResource)">Ver agenda no catálogo</button><button v-if="['rejected','expired','cancelled'].includes(status)" class="secondary-button" @click="begin">Reabrir formulário</button><button class="secondary-button" :disabled="busy" @click="close">Fechar</button></div>
   </template>
  </template>
 </section>
</template>

<style scoped>
